"""Agentic Compass - AI Agent Self-Reflection Tool

Reads local memory files and produces a structured Agent Action Plan.
"""

import argparse
import re
from pathlib import Path


def parse_args():
    parser = argparse.ArgumentParser(description='Agentic Compass - AI Agent Self-Reflection')
    parser.add_argument('--daily', default='memory/2026-01-31.md', help='Path to daily memory file')
    parser.add_argument('--long', default='MEMORY.md', help='Path to long-term memory file')
    parser.add_argument('--logs', default='logs/tool-errors.log', help='Path to tool error logs')
    parser.add_argument('--write', action='store_true', help='Write output to memory/agentic-compass.md')
    return parser.parse_args()


def read_file(path):
    try:
        return Path(path).read_text(encoding='utf-8')
    except FileNotFoundError:
        return ''


def analyze_completion_rate(daily_content):
    """Count [DONE] markers vs total tasks mentioned"""
    done_count = len(re.findall(r'\[DONE\]', daily_content))
    task_count = len(re.findall(r'-\s+(Started|Retried|Forgot|Proposed|Implemented|Completed)', daily_content, re.IGNORECASE))
    if task_count == 0:
        return 0.5, 0
    rate = done_count / max(task_count, 1)
    return min(rate, 1.0), done_count


def analyze_response_relevance(daily_content):
    """Check for explicit confirmations or corrections mentioned"""
    corrections = len(re.findall(r'(correction|retry|timeout|error)', daily_content, re.IGNORECASE))
    if corrections == 0:
        return 0.9, 0
    return max(0.5, 0.9 - (corrections * 0.1)), corrections


def analyze_tool_quality(logs_content):
    """Parse tool error logs"""
    error_count = len(re.findall(r'(error|timeout|fail)', logs_content, re.IGNORECASE))
    if error_count == 0:
        return 1.0, 0
    return max(0.3, 1.0 - (error_count * 0.15)), error_count


def analyze_memory_consistency(daily_content, long_content):
    """Track forgotten decisions or inconsistencies"""
    forgotten = len(re.findall(r'forgot|remember', daily_content, re.IGNORECASE))
    if forgotten == 0:
        return 1.0, 0
    return max(0.4, 1.0 - (forgotten * 0.2)), forgotten


def analyze_initiative(daily_content):
    """Count proactive actions"""
    proactive = len(re.findall(r'(proposed|proactive|without being asked|started.*\[DONE\])', daily_content, re.IGNORECASE))
    return min(1.0, 0.5 + (proactive * 0.25)), proactive


def find_weakest_axis(scores):
    """Find the axis with lowest score"""
    return min(scores.items(), key=lambda x: x[1])


